use super::*;
use super::super::shortcuts::ShortcutsPage;
fn form(a:&Workspace)->Rc<ShortcutsPage>{let widget=a.current_widget().unwrap();a.shortcut_pages.borrow().iter().find(|p|p.widget.upcast_ref::<gtk::Widget>()==&widget).unwrap().clone()}
fn open(a:&Rc<Workspace>)->Rc<ShortcutsPage>{a.keyboard_shortcuts();wait(||a.shortcut_pages.borrow().iter().any(|p|p.loaded.get()&&a.current_widget()==Some(p.widget.clone().upcast())));form(a)}
fn entry(p:&ShortcutsPage,action:&str)->gtk::Entry{p.entries.iter().find(|(id,_)|id==action).unwrap().1.clone()}
fn save_form(a:&Rc<Workspace>,p:&Rc<ShortcutsPage>)->Result<(),String>{let result=Rc::new(RefCell::new(None));let out=result.clone();a.save_current(move|r|*out.borrow_mut()=Some(r));wait(||result.borrow().is_some()&&!p.saving.get());let value=result.borrow_mut().take().unwrap();value}
fn key(key:gdk::keys::Key,state:gdk::ModifierType)->gdk::EventKey{let mut event=gdk::Event::new(gdk::EventType::KeyPress);let raw=event.downcast_mut::<gdk::EventKey>().unwrap().as_mut();raw.keyval=*key;raw.state=state.bits();event.downcast::<gdk::EventKey>().unwrap()}
pub(super) fn run(binaries:&Path){
    let fixture=tempfile::tempdir().unwrap();let data=fixture.path().join("shortcut-data");let cache=fixture.path().join("shortcut-cache");std::fs::create_dir_all(&data).unwrap();std::fs::create_dir_all(&cache).unwrap();
    let companion=if binaries.join("novel-companion-rust").is_file(){"novel-companion-rust"}else{"novel-companion"};let client=Process::start(&binaries.join(companion),&data,true).unwrap();let project=rpc(&client,"create_novel",json!({"title":"Shortcuts"}));let pid=project["project"]["id"].as_str().unwrap();let sid=project["scene"]["id"].as_str().unwrap();
    let settings=json!({"schemaVersion":1,"authorPreference":{"text":"مِ 中文 𠀀 👩🏽‍🚀"}});rpc(&client,"save_project_data",json!({"projectId":pid,"kind":"settings","payload":settings,"parent":null}));
    let a=Workspace::build(client,&cache,binaries,false,false).unwrap();wait(||a.active.borrow().as_ref().is_some_and(|p|p.open.get()&&p.pending.get()==0)&&a.shortcuts.loaded.get());
    let manuscript=a.active.borrow().clone().unwrap();edit(&manuscript,"Shortcut writing مِ 中文 𠀀 👩🏽‍🚀");save(&a,&manuscript);
    let original=rpc(&a.client,"load_scene",json!({"sceneId":sid}));let p=open(&a);let marker=rpc(&a.client,"sync_cursor",json!({}));entry(&p,"editor.bold").set_text("Ctrl+Shift+B");entry(&p,"workspace.save").set_text("Ctrl+Shift+S");pump(Duration::from_millis(150));assert!(p.dirty.get());assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    select(&a,SaveChoice::Cancel);a.open_book();assert_eq!(a.current_widget(),Some(p.widget.clone().upcast()));assert!(p.dirty.get());
    entry(&p,"editor.bold").set_text("Ctrl+Shift+S");assert!(save_form(&a,&p).unwrap_err().contains("more than once"));assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);entry(&p,"editor.bold").set_text("Ctrl+Alt+B");assert!(save_form(&a,&p).unwrap_err().contains("AltGr"));assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    p.discard();entry(&p,"editor.bold").set_text("Ctrl+Shift+B");entry(&p,"workspace.save").set_text("Ctrl+Shift+S");capture(&a,"notebook-keyboard-shortcuts.png");find_button(&p.widget,"Save shortcuts").unwrap().clicked();wait(||!p.saving.get()&&!p.dirty.get());let saved=rpc(&a.client,"load_project_data",json!({"projectId":pid,"kind":"settings"}));assert_eq!(saved["payload"]["authorPreference"],settings["authorPreference"]);assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":sid})),original);
    // A disabled default chord is no longer handled, and the remapped chord acts once.
    a.open_scene(sid,false);wait(||a.current_widget()==Some(manuscript.widget.clone().upcast()));let ctrl=gdk::ModifierType::CONTROL_MASK;let shift=ctrl|gdk::ModifierType::SHIFT_MASK;
    manuscript.operation(json!({"type":"command","command":"selectAll"}),false);wait(||manuscript.pending.get()==0);
    assert!(super::super::shortcuts::editor_shortcut(&manuscript,&key(gdk::keys::constants::b,ctrl)).is_none());
    assert_eq!(super::super::shortcuts::editor_shortcut(&manuscript,&key(gdk::keys::constants::B,shift)),Some(glib::Propagation::Stop));wait(||manuscript.pending.get()==0&&manuscript.dirty.get());let bold=manuscript.frame.borrow()["document"].clone();assert!(bold["content"][0]["content"][0]["marks"].as_array().unwrap().iter().any(|m|m["type"]=="bold"));assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":sid})),original);
    // Composition blocks a recognized operation; Ctrl+Alt passes through to IME.
    manuscript.composing.set(true);assert_eq!(super::super::shortcuts::editor_shortcut(&manuscript,&key(gdk::keys::constants::B,shift)),Some(glib::Propagation::Stop));pump(Duration::from_millis(80));assert_eq!(manuscript.frame.borrow()["document"],bold);manuscript.composing.set(false);assert!(super::super::shortcuts::editor_shortcut(&manuscript,&key(gdk::keys::constants::b,ctrl|gdk::ModifierType::MOD1_MASK)).is_none());
    assert_eq!(super::super::shortcuts::editor_shortcut(&manuscript,&key(gdk::keys::constants::S,shift)),Some(glib::Propagation::Proceed));assert_eq!(a.workspace_shortcut(&key(gdk::keys::constants::s,ctrl)),glib::Propagation::Proceed);assert_eq!(a.workspace_shortcut(&key(gdk::keys::constants::S,shift)),glib::Propagation::Stop);wait(||!manuscript.saving.get()&&!manuscript.dirty.get());assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":sid}))["scene"]["document"],bold);
    // An old form cannot overwrite a newer window's preference edits.
    let stale=open(&a);entry(&stale,"editor.italic").set_text("Ctrl+Shift+I");let child=a.spawn_window();let fresh=open(&child);entry(&fresh,"editor.underline").set_text("Ctrl+Shift+U");save_form(&child,&fresh).unwrap();let marker=rpc(&a.client,"sync_cursor",json!({}));assert!(save_form(&a,&stale).unwrap_err().contains("Conflict"));assert!(stale.dirty.get());assert_eq!(entry(&stale,"editor.italic").text(),"Ctrl+Shift+I");assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);
    select(&a,SaveChoice::Discard);let detached_form=open(&a);entry(&detached_form,"editor.italic").set_text("Ctrl+Shift+I");a.detach_current();let detached=last_window();assert!(Rc::ptr_eq(&form(&detached),&detached_form));find_button(&detached_form.widget,"Save shortcuts").unwrap().clicked();wait(||!detached_form.saving.get()&&!detached_form.dirty.get());
    a.close();wait(||windows()==2);entry(&detached_form,"editor.bold").set_text(" ");save_form(&detached,&detached_form).unwrap();assert_eq!(rpc(&detached.client,"load_project_data",json!({"projectId":pid,"kind":"settings"}))["payload"]["nativeShortcuts"]["bindings"]["editor.bold"],json!([]));
    detached.close();wait(||windows()==1);child.close();wait(||windows()==0);conflicted_optional_preferences(binaries);
}
fn conflicted_optional_preferences(binaries:&Path){
    let fixture=tempfile::tempdir().unwrap();let data=fixture.path().join("conflicted-shortcuts");let peer_data=fixture.path().join("conflicted-peer");let cache=fixture.path().join("conflicted-cache");for path in [&data,&peer_data,&cache]{std::fs::create_dir_all(path).unwrap();}
    let companion=if binaries.join("novel-companion-rust").is_file(){"novel-companion-rust"}else{"novel-companion"};let client=Process::start(&binaries.join(companion),&data,true).unwrap();let peer=Process::start(&binaries.join(companion),&peer_data,true).unwrap();let project=rpc(&client,"create_novel",json!({"title":"Conflicted optional settings"}));let pid=project["project"]["id"].as_str().unwrap();let sid=project["scene"]["id"].as_str().unwrap();
    let original=rpc(&client,"load_scene",json!({"sceneId":sid}));let mut rich=original["scene"].clone();rich["document"]=json!({"type":"doc","content":[{"type":"paragraph","attrs":{"dir":"rtl","lang":"ar"},"content":[{"type":"text","text":"Unchanged مِ 中文 𠀀 👩🏽‍🚀 e\u{301}"}]}]});let original=rpc(&client,"save_scene",json!({"sceneId":sid,"scene":rich,"parent":original["revisionId"]}));
    let mut shortcuts=novel_storage::native_shortcuts::NativeShortcutSettings::default();shortcuts.bindings.insert("workspace.save".into(),novel_storage::native_shortcuts::parse_native_shortcut_list("Ctrl+Shift+S").unwrap());shortcuts.bindings.insert("editor.bold".into(),novel_storage::native_shortcuts::parse_native_shortcut_list("F8").unwrap());let payload=json!({"schemaVersion":1,"nativeShortcuts":shortcuts,"nativeDesk":{"schemaVersion":1,"direction":"rtl","writingWidth":420},"authorPreference":"Baseline مِ 中文"});let baseline=rpc(&client,"save_project_data",json!({"projectId":pid,"kind":"settings","payload":payload,"parent":null}));
    let transfer=|from:&Process,to:&Process|{let source=rpc(from,"sync_cursor",json!({}));let target=rpc(to,"sync_cursor",json!({}));let revisions=rpc(from,"pull_revisions",json!({"projectId":pid,"cursor":{"epoch":source["epoch"],"sequence":0},"limit":1000}));rpc(to,"ingest_revisions",json!({"projectId":pid,"expectedEpoch":target["epoch"],"remoteEpoch":source["epoch"],"manifest":rpc(from,"open_project",json!({"projectId":pid})),"revisions":revisions["revisions"]}));};transfer(&client,&peer);
    let mut left=payload.clone();left["authorPreference"]=json!("Left author");let mut right=payload;right["authorPreference"]=json!("Right author");rpc(&client,"save_project_data",json!({"projectId":pid,"kind":"settings","payload":left,"parent":baseline["revisionId"]}));rpc(&peer,"save_project_data",json!({"projectId":pid,"kind":"settings","payload":right,"parent":baseline["revisionId"]}));transfer(&peer,&client);let marker=rpc(&client,"sync_cursor",json!({}));
    let a=Workspace::build(client,&cache,binaries,false,false).unwrap();wait(||a.shortcuts.loaded.get()&&a.desktop_preferences.loaded.get()&&a.active.borrow().as_ref().is_some_and(|p|p.open.get()&&p.pending.get()==0));let pane=a.active.borrow().clone().unwrap();assert_eq!(a.window.direction(),gtk::TextDirection::Ltr);assert!(pane.area.allocated_width()>420);let notice=a.optional_preferences_notice().unwrap();assert!(notice.contains("built-in keyboard shortcuts")&&notice.contains("built-in writing view"));assert_eq!(pane.frame.borrow()["document"],rich["document"]);
    let ctrl=gdk::ModifierType::CONTROL_MASK;assert_eq!(a.workspace_shortcut(&key(gdk::keys::constants::s,ctrl)),glib::Propagation::Stop);assert_eq!(a.workspace_shortcut(&key(gdk::keys::constants::S,ctrl|gdk::ModifierType::SHIFT_MASK)),glib::Propagation::Proceed);pane.operation(json!({"type":"command","command":"selectAll"}),false);wait(||pane.pending.get()==0);assert_eq!(super::super::shortcuts::editor_shortcut(&pane,&key(gdk::keys::constants::b,ctrl)),Some(glib::Propagation::Stop));wait(||pane.pending.get()==0);assert!(pane.dirty.get());let discarded=Rc::new(RefCell::new(None));let out=discarded.clone();pane.discard(move|result|*out.borrow_mut()=Some(result));wait(||discarded.borrow().is_some());assert!(discarded.borrow_mut().take().unwrap().is_ok());assert_eq!(pane.frame.borrow()["document"],rich["document"]);
    a.keyboard_shortcuts();wait(||a.shortcut_pages.borrow().last().is_some_and(|p|p.status.text().contains("editing unavailable")));let p=form(&a);assert!(!p.loaded.get());assert!(!entry(&p,"workspace.save").is_sensitive());assert!(save_form(&a,&p).is_err());
    a.writing_view();wait(||a.desktop_preference_pages.borrow().last().is_some_and(|p|p.status.text().contains("editing unavailable")));let view=a.desktop_preference_pages.borrow().last().unwrap().clone();assert!(!view.loaded.get());assert!(!view.direction.is_sensitive());let result=Rc::new(RefCell::new(None));let out=result.clone();view.save(&a,move|r|*out.borrow_mut()=Some(r));assert!(result.borrow_mut().take().unwrap().is_err());assert_eq!(rpc(&a.client,"sync_cursor",json!({})),marker);assert_eq!(rpc(&a.client,"load_scene",json!({"sceneId":sid})),original);a.close();wait(||windows()==0);peer.stop();
}
